INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Addressee of the representation letter
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should be addressed to:', '["The auditor", "The audit committee", "The board of directors", "The entity''s legal counsel"]'::jsonb, 0, 'Under AU-C 580, the management representation letter is addressed to the auditor because the letter constitutes direct communication confirming matters discussed during the audit. Choice B is incorrect because the audit committee receives separate communications under AU-C 260 regarding significant audit findings, not the representation letter itself.', 'easy', 1),

-- Q2: easy / L2 — Completeness of transactions representation
(1, 'Written Representations', 'During the audit of Lakewood Supply Co.''s December 31, 2025 financial statements, the engagement partner at Foster & Klein CPA prepares the representation letter for management''s signature. Under AU-C 580, which representation must management provide regarding transaction completeness?', '["That all transactions exceeding materiality have been recorded", "That all transactions have been recorded and are reflected in the financial statements", "That all material transactions have been disclosed to the audit committee", "That a complete list of journal entries has been provided to the auditor"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that all transactions have been recorded and are reflected in the financial statements. This completeness representation is not limited to transactions exceeding materiality (choice A), because even individually immaterial transactions can be material in the aggregate. The representation covers all transactions, not just those above a threshold.', 'easy', 2),

-- Q3: hard / L4 — Contradictory evidence vs written representations
(1, 'Written Representations', 'During the audit of Belmont Aerospace Inc. for the year ended December 31, 2025, the engagement team at Crawford & Patel CPA obtains a management representation letter stating that all related-party transactions have been disclosed. However, the team independently identifies three undisclosed transactions with entities controlled by the CFO''s spouse. The engagement partner must evaluate the implications. Under AU-C 580, the auditor should:', '["Accept the written representation as sufficient and issue an unmodified opinion", "Request revised financial statements and obtain a new representation letter", "Reconsider the reliability of all other representations from management and assess the effect on the audit opinion", "Immediately withdraw from the engagement and report the matter to the SEC"]'::jsonb, 2, 'Under AU-C 580.A29, when audit evidence contradicts written representations, the auditor must reconsider whether the representations are reliable overall and evaluate the effect on the audit opinion. Contradictory evidence raises doubt about management''s integrity and the reliability of all representations. Choice B is incorrect because simply requesting revised statements does not address the fundamental concern about whether management''s representations can be relied upon at all.', 'hard', 4),

-- Q4: medium / L2 — Going concern representations
(1, 'Written Representations', 'Meridian Healthcare Corp. is experiencing significant financial difficulties during its December 31, 2025 audit by Harper & Wells CPA. The auditor notes substantial doubt about Meridian''s ability to continue as a going concern. Under AU-C 580, what specific representation should the auditor request regarding going concern?', '["That the entity will maintain profitability for the next five years", "That the entity intends to liquidate within 12 months", "That management has prepared a detailed bankruptcy filing plan", "That management''s plans to mitigate the going concern doubt are feasible and have been fully disclosed"]'::jsonb, 3, 'Under AU-C 580.A14, when substantial doubt exists about going concern, the auditor should obtain representations from management about its plans to address the conditions and the feasibility of those plans. Choice A is incorrect because the representation concerns management''s plans and their disclosure, not a guarantee of future profitability, which no representation can provide.', 'medium', 2),

-- Q5: medium / L3 — Effect on risk assessment when representations appear unreliable
(1, 'Written Representations', 'During the audit of Pinnacle Construction Group for the year ended December 31, 2025, the engagement partner at Monroe & Associates discovers that management previously provided inaccurate representations about a material contingency during interim fieldwork. As the team prepares to request the final representation letter, the partner analyzes how this discovery most likely affects the audit. The most significant implication is that the auditor should:', '["Increase the assessed risk of material misstatement and expand substantive procedures", "Accept a revised representation with additional corroborating language", "Defer obtaining the final representation letter until the contingency is resolved", "Reduce reliance on inquiry and increase reliance on observation"]'::jsonb, 0, 'Under AU-C 580.A26, when written representations are inconsistent with other audit evidence or appear unreliable, the auditor should reconsider the assessed risk of material misstatement and expand procedures accordingly. The discovery of previously inaccurate representations signals heightened risk. Choice B is incorrect because simply accepting a revised representation does not address the underlying concern about management''s reliability and integrity.', 'medium', 3),

-- Q6: medium / L2 — Period covered by representations
(1, 'Written Representations', 'Waverly Financial Services presents comparative financial statements for the years ended December 31, 2024 and 2025. The engagement team at Gilbert & Clarke CPA is preparing the management representation letter. Under AU-C 580, the representation letter should cover:', '["Only the current year financial statements", "All periods covered by the auditor''s report on the comparative financial statements", "The most recent fiscal quarter only", "Only periods in which the auditor identified adjustments"]'::jsonb, 1, 'Under AU-C 580.14, the representation letter must cover all periods referred to in the auditor''s report. When comparative financial statements are presented, the representations extend to all periods covered by the opinion. Choice A is incorrect because limiting representations to the current year would leave the auditor without required representations for the prior period financial statements included in the comparative presentation.', 'medium', 2),

-- Q7: hard / L4 — Evaluating when management's knowledge is limited
(1, 'Written Representations', 'During the audit of Arcadia Ventures LLC for the year ended December 31, 2025, the CEO and CFO both joined in October 2025. They are willing to sign the management representation letter but express concern about representing matters for the first nine months. The engagement partner at Sherman & Quinn CPA evaluates how to proceed. Under AU-C 580, the most appropriate course of action is to:', '["Waive the representation letter requirement given the extenuating circumstances", "Accept representations limited only to the final three months of the fiscal year", "Issue a disclaimer of opinion because management cannot fully represent the entire year", "Obtain the representation letter covering the full period, as management is expected to make inquiries sufficient to provide the required representations"]'::jsonb, 3, 'Under AU-C 580.A8, management provides representations based on their knowledge after having made inquiries they consider appropriate. New management is expected to take steps to become informed about matters covered in the representations, including reviewing prior records and making inquiries of predecessor management. Choice B is incorrect because limiting representations to only part of the period would leave the auditor without required representations for the full reporting period.', 'hard', 4),

-- Q8: medium / L2 — Representation about access to all records
(1, 'Written Representations', 'The engagement team at Aldridge & Park CPA completes fieldwork for Oakmont Distribution Corp.''s December 31, 2025 audit. As part of the representation letter, the auditor requests that management confirm access to information. Under AU-C 580, management should represent that the auditor has been provided with:', '["All documents the auditor specifically requested during fieldwork", "Access only to accounting records directly related to the financial statements", "Access to all information relevant to the preparation of the financial statements, including additional information requested and unrestricted access to persons within the entity", "A complete copy of all electronic records maintained on the entity''s servers"]'::jsonb, 2, 'Under AU-C 580.11(b), management must represent that the auditor has been provided all information relevant to the financial statements, any additional information the auditor requested, and unrestricted access to persons within the entity the auditor determined necessary. Choice A is incorrect because the representation extends beyond specifically requested documents to all information relevant to the preparation and fair presentation of the financial statements.', 'medium', 2),

-- Q9: medium / L2 — Representation about subsequent events
(1, 'Written Representations', 'The auditor at Mitchell & Rowe CPA is drafting the management representation letter for Crestview Partners LLC''s audit for the year ended December 31, 2025. The auditor''s report date is March 2, 2026. Under AU-C 580, the representation letter should include a specific statement about subsequent events. This representation requires management to confirm that:', '["All events occurring after the balance sheet date that require adjustment or disclosure have been properly addressed in the financial statements", "No events occurred between the balance sheet date and the report date", "The entity experienced no adverse financial changes during the subsequent period", "All subsequent events were reported to the audit committee before the report date"]'::jsonb, 0, 'Under AU-C 580.11, the representation letter includes a statement that all events occurring subsequent to the date of the financial statements requiring adjustment or disclosure have been properly reflected. Choice B is incorrect because the representation does not claim that no events occurred; rather, it confirms that events requiring adjustment or disclosure have been properly treated in the financial statements.', 'medium', 2),

-- Q10: easy / L1 — Written vs oral representations
(1, 'Written Representations', 'Under AU-C 580, why are written representations required even when management has provided oral assurances on the same matters?', '["Oral assurances are inadmissible as evidence under GAAS", "Written representations are needed only when the auditor doubts management''s integrity", "Oral representations are sufficient for immaterial items but not material ones", "Written representations reduce the possibility of misunderstandings and provide a formal record of the representations made"]'::jsonb, 3, 'Under AU-C 580.06, written representations are required because they reduce the possibility of misunderstandings between management and the auditor and provide documentation of the representations made. Choice A is incorrect because oral representations are not inadmissible — they are a form of audit evidence through inquiry — but written representations formalize them and provide a documentary record.', 'easy', 1),

-- Q11: hard / L4 — Evaluating representations about accounting estimates
(1, 'Written Representations', 'During the audit of Sterling Capital Advisors for the year ended December 31, 2025, management provides a representation that its $14.2 million fair value estimate for illiquid private equity investments is based on reasonable assumptions. The engagement team at Whitmore & Drake CPA notes that management used internally developed models without independent market data and that assumptions differ significantly from comparable firms. The auditor should evaluate this situation by:', '["Accepting the representation because management bears primary responsibility for fair value estimates", "Assessing whether the representations are consistent with audit evidence and whether additional procedures are needed for the estimate", "Declining to issue an opinion until an independent valuation is obtained", "Requiring management to amend the representation letter to disclose the use of internally developed models"]'::jsonb, 1, 'Under AU-C 580.A25, the auditor cannot rely solely on written representations as sufficient appropriate audit evidence. When representations about estimates involve significant judgment, the auditor must corroborate them with other evidence and evaluate the estimate''s methods, data, and assumptions per AU-C 540. Choice A is incorrect because while management is responsible for estimates, the auditor must independently evaluate whether the assumptions are reasonable.', 'hard', 4),

-- Q12: easy / L1 — Representation about compliance with laws and regulations
(1, 'Written Representations', 'Under AU-C 580, management''s representation letter typically includes a statement regarding compliance with laws and regulations. This representation confirms that:', '["The entity has never been subject to any regulatory investigations", "The entity''s legal counsel has certified full regulatory compliance", "All known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements have been disclosed to the auditor", "The entity is in full compliance with all applicable federal and state regulations"]'::jsonb, 2, 'Under AU-C 580.11, the representation letter includes disclosure of known noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements. Choice D is incorrect because the representation does not guarantee full compliance with all laws; rather, it confirms that known or suspected instances of noncompliance have been disclosed to the auditor.', 'easy', 1),

-- Q13: easy / L1 — Representation about title to assets
(1, 'Written Representations', 'Under AU-C 580, the management representation letter includes a statement confirming that the entity has:', '["Satisfactory title to, or control over, all recognized assets", "Insurance coverage for all tangible assets", "Appraised all assets at fair market value within the past year", "Pledged no assets as collateral for any obligations"]'::jsonb, 0, 'Under AU-C 580.11, management represents that the entity has satisfactory title to, or control over, all recognized assets. This representation supports the rights and obligations assertion for balance sheet accounts. Choice D is incorrect because the title representation does not mean assets have not been pledged — it confirms ownership or control, while pledged assets would be disclosed separately.', 'easy', 1),

-- Q14: medium / L3 — Entity-specific (additional) representations
(1, 'Written Representations', 'During the audit of Prescott Marine Equipment Co. for the year ended December 31, 2025, the engagement team at Dunlap & Nix CPA identifies complex environmental remediation obligations, contingent liabilities from pending patent litigation, and government contracts with specific compliance requirements. The auditor analyzes what additional representations are needed. Under AU-C 580, the most likely effect of these factors is that the auditor should:', '["Rely solely on the standard representation letter language prescribed by AU-C 580", "Request entity-specific representations tailored to Prescott''s unique circumstances, including representations about completeness of environmental liabilities, litigation disclosures, and government contract compliance", "Limit additional representations to the single most material issue identified", "Obtain representations only if management volunteers the additional information"]'::jsonb, 1, 'Under AU-C 580.A12, the auditor should request additional representations specific to the entity''s circumstances when complex or unusual matters exist. Entity-specific representations supplement the standard required representations and address areas where the auditor needs particular assurance. Choice A is incorrect because the standard template language may not adequately address entity-specific risks such as environmental obligations or government contract requirements.', 'medium', 3),

-- Q15: medium / L2 — Representation about uncorrected misstatements
(1, 'Written Representations', 'During the audit of Northridge Electronics Inc. for the year ended December 31, 2025, the engagement team at Caldwell & Shaw CPA identifies three uncorrected misstatements totaling $38,000, below the $50,000 materiality threshold. The auditor prepares the summary of uncorrected misstatements. Under AU-C 580, the management representation letter should include a statement that management:', '["Has corrected all identified misstatements before signing the letter", "Acknowledges that no misstatements exist in the financial statements", "Will correct all misstatements in the subsequent period", "Believes the effects of uncorrected misstatements, individually and in the aggregate, are immaterial to the financial statements as a whole"]'::jsonb, 3, 'Under AU-C 580.11, management must acknowledge that uncorrected misstatements aggregated by the auditor are immaterial, both individually and in the aggregate, to the financial statements as a whole. A summary of these items is typically attached to or referenced in the representation letter. Choice B is incorrect because the representation acknowledges that misstatements were identified but asserts they are immaterial, not that no misstatements exist.', 'medium', 2),

-- Q16: medium / L3 — Representations about accounting policy changes
(1, 'Written Representations', 'Cascade Technology Group changed its revenue recognition method during the year ended December 31, 2025, switching from recognizing revenue at a point in time to an over-time model for its software implementation services. The engagement team at Mercer & Ford CPA analyzes how this change affects the representation letter. Under AU-C 580, the most likely effect is that the auditor should:', '["Accept the change without additional representations if it complies with ASC 606", "Limit the representation to a statement that all accounting policies were properly applied", "Request a specific representation that the new accounting policy is appropriate under the applicable framework and the change is properly disclosed", "Require management to reverse the accounting policy change to the prior method"]'::jsonb, 2, 'Under AU-C 580.11, management must represent that the methods, significant assumptions, and data used in making accounting estimates are appropriate. When an accounting policy change occurs, the auditor should request specific representations about the appropriateness of the new policy and the adequacy of disclosure. Choice A is incorrect because even if the change complies with the framework, the auditor needs explicit written representation confirming the appropriateness and proper disclosure.', 'medium', 3),

-- Q17: medium / L2 — Representation about absence of unrecorded liabilities
(1, 'Written Representations', 'The engagement team at Blake & Patterson CPA is finalizing the management representation letter for Summit Logistics Corp.''s December 31, 2025 audit. The auditor requests a specific representation about liabilities. Under AU-C 580, management should represent that:', '["All liabilities, both actual and contingent, have been recorded or disclosed in the financial statements", "All liabilities exceeding $10,000 have been recorded", "Only liabilities confirmed by third parties have been recorded", "All liabilities have been paid as of the balance sheet date"]'::jsonb, 0, 'Under AU-C 580.11, management must represent that all known actual and contingent liabilities have been properly recorded or disclosed. This representation addresses the completeness assertion for liabilities and ensures management has not omitted significant obligations. Choice B is incorrect because the representation covers all liabilities, not just those exceeding a particular dollar threshold, since even individually small liabilities may be material in the aggregate.', 'medium', 2),

-- Q18: medium / L2 — Representation about liens, pledges, or encumbrances
(1, 'Written Representations', 'During the audit of Ridgeway Manufacturing Inc. for the year ended December 31, 2025, the engagement team at Sullivan & Pratt CPA discovers that several pieces of equipment are pledged as collateral for a credit facility. The auditor prepares the representation letter. Under AU-C 580, management''s representation about pledged assets should confirm that:', '["No assets are pledged as collateral for any obligations", "All liens, pledges, and encumbrances on assets have been disclosed to the auditor and are properly reflected in the financial statements", "Pledged assets have been appraised within the last six months", "The total value of pledged assets does not exceed 50% of total assets"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that all liens, encumbrances, and pledges of assets have been disclosed and properly presented. This representation supports the disclosure and rights/obligations assertions. Choice A is incorrect because the representation does not assert that no assets are pledged — it confirms that any existing pledges have been disclosed and properly reflected in the financial statements.', 'medium', 2),

-- Q19: easy / L1 — Management's knowledge as basis for representations
(1, 'Written Representations', 'Under AU-C 580, management provides written representations to the auditor based on:', '["Only matters that management can prove with documentary evidence", "Matters personally witnessed by the CEO and CFO", "Information provided exclusively by the entity''s legal counsel", "Management''s knowledge, after making inquiries that management considers appropriate"]'::jsonb, 3, 'Under AU-C 580.A8, management provides written representations based on its knowledge, including knowledge obtained through inquiries management considers appropriate. Choice A is incorrect because representations are not limited to matters management can prove with documentation, as many representations involve judgments and assessments that require management to make reasonable inquiries within the organization.', 'easy', 1),

-- Q20: easy / L1 — Representation about proper classification and disclosure
(1, 'Written Representations', 'Under AU-C 580, the management representation letter includes a statement about the classification, presentation, and disclosure of financial statement items. This representation confirms that:', '["All transactions have been audited by an independent party", "The financial statements have been reviewed by the audit committee", "Financial statement items have been properly classified, described, and disclosed in conformity with the applicable financial reporting framework", "All disclosures follow the exact format prescribed by the SEC"]'::jsonb, 2, 'Under AU-C 580.11, management must represent that the financial statements are fairly presented, including that items are properly classified, described, and disclosed in accordance with the applicable financial reporting framework. Choice A is incorrect because the representation concerns management''s responsibility for presentation and disclosure, not whether an independent party audited individual transactions.', 'easy', 1),

-- Q21: easy / L1 — Representation about management's responsibility for internal control
(1, 'Written Representations', 'Under AU-C 580, management''s written representations include an acknowledgment of management''s responsibility for:', '["Issuing the auditor''s report on internal controls", "The design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements", "Performing all internal control testing procedures", "Guaranteeing that internal controls prevent all fraud"]'::jsonb, 1, 'Under AU-C 580.10, management must acknowledge its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements free from material misstatement. Choice D is incorrect because internal controls provide reasonable, not absolute, assurance, and management does not guarantee fraud prevention.', 'easy', 1),

-- Q22: hard / L4 — Side agreements or undisclosed arrangements
(1, 'Written Representations', 'During the audit of Keystone Properties LLC for the year ended December 31, 2025, the engagement partner at Warren & Dalton CPA discovers an unrecorded side agreement between Keystone and a major tenant that modifies lease terms significantly. Management initially omitted this from disclosures and from the representation letter. When confronted, management claims the agreement is immaterial. The engagement partner should evaluate this situation by:', '["Reconsidering the reliability of all representations and determining the effect on the audit opinion", "Accepting management''s materiality assessment and issuing an unmodified opinion", "Adding a footnote to the representation letter noting the omission", "Deferring the audit opinion until the next fiscal year"]'::jsonb, 0, 'Under AU-C 580.A29, when the auditor identifies evidence that management did not provide complete or accurate representations, the auditor must reconsider the reliability of all representations. A deliberate omission raises concerns about management''s integrity, which may have pervasive effects on the audit. Choice B is incorrect because the auditor cannot simply accept management''s materiality assessment when the omission itself raises questions about the completeness and reliability of all representations.', 'hard', 4),

-- Q23: medium / L3 — Representation considerations in an initial audit
(1, 'Written Representations', 'Barrett & Singh CPA is performing the initial audit of Coastal Dynamics Corp. for the year ended December 31, 2025. The prior year financial statements were audited by a different firm. The engagement team considers what representations are needed. Under AU-C 580, the most likely additional consideration is that the auditor should:', '["Request that the predecessor auditor provide the representation letter from the prior year", "Limit representations to only the current year since the prior auditor covered the prior period", "Rely entirely on the predecessor auditor''s workpapers for prior-period representations", "Obtain representations covering all periods presented in the comparative financial statements, including matters related to opening balances"]'::jsonb, 3, 'Under AU-C 580.14, the representation letter must cover all periods referred to in the auditor''s report. For an initial audit with comparative statements, the successor auditor obtains representations covering all presented periods, including matters related to opening balances. Choice B is incorrect because the current auditor is responsible for representations supporting the opinion on all periods presented, regardless of whether a predecessor audited the prior period.', 'medium', 3),

-- Q24: medium / L3 — Representations from those charged with governance
(1, 'Written Representations', 'During the audit of Westlake Community Foundation for the year ended December 31, 2025, the engagement team at Harper & Nolan CPA identifies that several significant governance decisions affecting the financial statements were made solely by the board of directors, with minimal management involvement. The auditor analyzes whether additional representations from the board are necessary. Under AU-C 580, the auditor should:', '["Omit those matters from the representation letter entirely", "Rely exclusively on board meeting minutes as a substitute for representations", "Request written representations from those charged with governance regarding matters within their specific responsibility", "Require management to represent on behalf of the board without board involvement"]'::jsonb, 2, 'Under AU-C 580.09, when representations relate to matters within the responsibility of those charged with governance, the auditor may need to obtain representations from those parties directly. This is particularly relevant for nonprofit entities where governance exercises direct authority over financial reporting matters. Choice D is incorrect because management cannot provide representations on behalf of governance for matters outside management''s direct knowledge and authority.', 'medium', 3),

-- Q25: medium / L2 — Representation about revenue recognition completeness
(1, 'Written Representations', 'During the audit of Avalon Software Solutions for the year ended December 31, 2025, the engagement team at Thornton & Reeves CPA discovers that Avalon has multiple performance obligations in many contracts. The auditor requests a specific representation about revenue. Under AU-C 580, the most relevant representation management should provide is that:', '["All revenue has been collected in cash by year-end", "Revenue has been recognized in conformity with the applicable framework, and all customer arrangements have been disclosed to the auditor", "Revenue exceeding the materiality threshold has been tested by management", "The external auditor is responsible for verifying revenue recognition"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that revenue is recognized in conformity with the applicable financial reporting framework and that all significant arrangements have been disclosed. When complex revenue arrangements exist, this representation helps address completeness and accuracy assertions. Choice A is incorrect because revenue recognition is based on transfer of control under ASC 606, not on cash collection, and the representation concerns proper recognition rather than collection.', 'medium', 2),

-- Q26: hard / L3 — Representation implications when management used a specialist
(1, 'Written Representations', 'Hartwell Biotech Inc. used an independent actuarial specialist to determine its $8.7 million pension obligation for the year ended December 31, 2025. The engagement team at Prescott & Vance CPA is preparing the representation letter. Management states that since an independent specialist prepared the estimate, it should not need to represent the reasonableness of the underlying assumptions. The auditor should analyze this position by concluding that:', '["Management retains responsibility for accounting estimates regardless of whether a specialist was used, and must still represent that the methods, data, and assumptions underlying the estimate are reasonable", "The specialist''s report eliminates the need for management representations about the pension obligation", "Management should represent only that a qualified specialist was engaged", "The auditor should obtain representations directly from the specialist instead of management"]'::jsonb, 0, 'Under AU-C 580.11 and AU-C 540, management is responsible for all accounting estimates in the financial statements, even when a specialist assists in their preparation. Management cannot delegate its representation responsibility to a specialist. Choice B is incorrect because the use of a specialist does not relieve management of its responsibility for the estimate or its obligation to represent that the methods, data, and assumptions are appropriate.', 'hard', 3),

-- Q27: hard / L4 — Evaluating whether management understands its responsibility
(1, 'Written Representations', 'During the audit of Ridgecrest Hospitality Group for the year ended December 31, 2025, the engagement partner at Calloway & Simms CPA observes that the CFO is willing to sign the management representation letter but appears unfamiliar with several representations and states, ''I will sign whatever you need.'' The engagement partner should evaluate this response by:', '["Accepting the signed letter at face value since it meets the formal requirement of AU-C 580", "Proceeding with the audit and noting the CFO''s comment in the workpapers as an administrative matter", "Having the controller sign the letter instead of the CFO", "Discussing each representation with the CFO to ensure management understands the matters being represented before signing"]'::jsonb, 3, 'Under AU-C 580.A4, the auditor should be satisfied that management understands the matters being represented. A representation signed without understanding may not constitute reliable audit evidence. The auditor should discuss the content with management to confirm comprehension. Choice A is incorrect because the mere act of signing does not satisfy the requirement — the auditor must be satisfied that management understands and acknowledges the matters being represented.', 'hard', 4),

-- Q28: easy / L1 — Representation about commitments and contingencies
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should include a statement regarding commitments and contingencies. This representation confirms that:', '["The entity has no outstanding legal disputes", "All commitments have been fully funded by the balance sheet date", "All known commitments and contingencies that require accrual or disclosure have been properly reflected in the financial statements", "The entity''s legal counsel has confirmed a favorable outcome for all pending litigation"]'::jsonb, 2, 'Under AU-C 580.11, management must represent that all known commitments and contingencies requiring accrual or disclosure under the applicable financial reporting framework have been properly reflected. Choice A is incorrect because the representation does not claim the entity has no legal disputes; rather, it confirms that any existing commitments and contingencies have been properly accrued or disclosed.', 'easy', 1),

-- Q29: medium / L3 — Relationship between representation date and subsequent events
(1, 'Written Representations', 'The engagement team at Palmer & Associates CPA dates the auditor''s report for Eastwood Corp.''s December 31, 2025 audit on March 3, 2026. On March 10, before the report is released, a material subsequent event occurs. The auditor extends subsequent events procedures to March 12 and changes the report date. Under AU-C 580, the most appropriate action regarding the representation letter is to:', '["Leave the original March 3 representation letter unchanged", "Obtain an updated or additional representation letter dated March 12 covering the extended subsequent events period", "Request that management verbally confirm the March 10 event without updating the letter", "Issue the report with the original March 3 date to avoid reopening the representation letter"]'::jsonb, 1, 'Under AU-C 580.14, the representation letter is dated as of the date of the auditor''s report. When the auditor extends subsequent events procedures and changes the report date, a new or updated representation letter covering the extended period is required. Choice A is incorrect because the original letter would not cover events between March 3 and March 12, leaving the auditor without required representations for the extended subsequent events period.', 'medium', 3),

-- Q30: medium / L3 — Written representations about concentration risk
(1, 'Written Representations', 'Bayview Components Inc. derives 78% of its revenue from a single customer, StrataCorp, for the year ended December 31, 2025. The engagement team at Duncan & Wells CPA reviews disclosure requirements and the representation letter. Under AU-C 580, the most appropriate action regarding this concentration is to:', '["Request a specific representation that all concentrations that could materially affect the financial statements, including the revenue concentration with StrataCorp, have been properly disclosed", "Omit the concentration from the representation letter since it is a business risk rather than an accounting matter", "Require management to diversify its customer base before the audit can be completed", "Accept the general completeness representation as sufficient to cover concentrations"]'::jsonb, 0, 'Under AU-C 580.A12, the auditor should request entity-specific representations for matters that could materially affect the financial statements. A significant customer concentration creates a vulnerability requiring disclosure, and a specific representation confirms completeness of that disclosure. Choice D is incorrect because the general completeness representation may not adequately address specific concentrations, and an explicit representation about the concentration provides stronger evidence.', 'medium', 3)
;

COMMIT;
